    create_response = sessions.create(
        name=name,
        parent_folder_id=PARENT_FOLDER_ID,
        size=len(payload),
        drive_id=drive_id,
        service_id=SERVICE_ID,
    )
    session_container = getattr(create_response, "create_upload_session_response", create_response)
    session_id = extract_first_id(session_container, f"upload session creation for {name}")

    sessions.upload(
        id=session_id,
        part_number=1,
        request_body=payload,
        service_id=SERVICE_ID

